"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["78893"],{62718(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.regra_eliminacao.area_e_minimo_obrigatorios","status":422,"titulo":"AreaCodigo e Minimo s\xe3o obrigat\xf3rios para a regra ELIMINACAO_CORTE_EM_AREA"},"descricao":{"codigo":"uniplus.selecao.regra_eliminacao.area_e_minimo_obrigatorios","requisitos":[],"oQueAconteceu":["Uma regra de elimina\xe7\xe3o com o c\xf3digo `ELIMINACAO_CORTE_EM_AREA` foi enviada com os\\ncampos errados. Essa regra elimina o candidato cuja nota em uma \xe1rea do ENEM\\nfica abaixo de um m\xednimo, e por isso exige `areaCodigo` e `minimo`. O erro\\nocorre quando falta um dos dois, ou quando a regra traz `etapaRef` ou\\n`notaMinima`, que pertencem a `ELIMINACAO_NOTA_MINIMA_ETAPA` e n\xe3o se aplicam aqui.\\nAs condi\xe7\xf5es s\xe3o conferidas juntas.","Esta confer\xeancia s\xf3 verifica que os campos certos foram informados. Se o\\n`areaCodigo` est\xe1 escrito num formato inv\xe1lido, ou se o `minimo` \xe9 negativo,\\na recusa vem de causas pr\xf3prias, que aparecem depois desta.\\nA primeira regra com problema interrompe a confer\xeancia, sem acumular com as\\ndemais. Nada foi gravado."],"comoResolver":["Para toda regra `ELIMINACAO_CORTE_EM_AREA`, informe `areaCodigo` e `minimo`, e n\xe3o\\ninforme `etapaRef` nem `notaMinima`."],"ondeAparece":["Defini\xe7\xe3o de classifica\xe7\xe3o do processo seletivo (`PUT /api/selecao/processos-seletivos/{id}/classificacao`)"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Regra eliminacao"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"418da40321f5e48caae8956b248f9336904d661a"}}')}}]);